"""Rebuild ../index.html from the source modules: python3 src/build.py (run from the repo root)."""
import os
here = os.path.dirname(os.path.abspath(__file__)); r = lambda f: open(os.path.join(here, f), encoding="utf-8").read()
h = r("app.html")
head = '<meta name="description" content="DeoCoach: the growth engine for coaches, trainers, facilitators, mentors and speakers — sense where opportunities are rising worldwide, read the culture of each city, find tenders, conferences and calls for speakers, and turn your capability into income. Includes the Edition for African Coaches.">\n<meta name="theme-color" content="#070d24"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-status-bar-style" content="black-translucent"><meta name="apple-mobile-web-app-title" content="DeoCoach"><link rel="manifest" href="/manifest.json"><link rel="icon" href="/icon-192.png"><link rel="apple-touch-icon" href="/apple-touch-icon.png">\n<meta property="og:title" content="DeoCoach · Activating the Future"><meta property="og:description" content="Capability to income, horizon foresight and cultural intelligence for coaches, trainers, facilitators, mentors and speakers — global, with an Africa edition."><meta property="og:image" content="/icon-512.png">'
out = h.replace("__D3GEO__", r("d3geo.min.js")).replace("__WORLD__", r("world.json")).replace("__DATA__", r("data.js") + "\n" + r("culture.js") + "\n" + r("fac_data.js") + "\n" + r("qr.js")).replace("__APP__", r("app.js") + "\n" + r("global.js") + "\n" + r("i18n.js") + "\n" + r("langs_data.js") + "\n" + r("engine.js") + "\n" + r("start.js") + "\n" + r("fas.js") + "\n" + r("mentor.js") + "\n" + r("events_data.js") + "\n" + r("events.js") + "\n" + r("bizdev.js") + "\n" + r("bodies.js") + "\n" + r("academies.js") + "\n" + r("free_data.js") + "\n" + r("founding.js") + "\n" + r("join.js") + "\n" + r("industry.js") + "\n" + r("atlas.js") + "\n" + r("polish.js"))
out = out.replace("<title>", head + "\n<title>", 1)
open(os.path.join(here, "..", "index.html"), "w", encoding="utf-8").write(out); print("index.html", len(out))
